function generateAssignments($n, $currentVertex, &$assignments, $vertexValues, $edges, &$maxDominoes) {
    if ($currentVertex > $n) {
        // Calculate how many dominoes can be placed with this assignment
        $dominoCount = calculateDominoes($assignments, $edges);
        if ($dominoCount > $maxDominoes) {
            $maxDominoes = $dominoCount;
        }
        return;
    }

    for ($val = 1; $val <= 6; $val++) {
        $assignments[$currentVertex] = $val;
        generateAssignments($n, $currentVertex + 1, $assignments, $vertexValues, $edges, $maxDominoes);
    }
}

function calculateDominoes($assignments, $edges) {
    $dominoSet = [];
    $count = 0;

    foreach ($edges as $edge) {
        $a = $edge[0];
        $b = $edge[1];
        $valA = $assignments[$a];
        $valB = $assignments[$b];

