    $domino_options = [];
    foreach ($dominoes as $dom) {
        $a = $dom[0];
        $b = $dom[1];
        $options = [];
        $options[] = [$a, $b];
        if ($a != $b) {
            $options[] = [$b, $a];
        }
        $domino_options[] = $options;
    }

    $max_count = 0;
    $total_dominoes = count($dominoes);

    // Backtracking function
    function backtrack($edge_idx, $used, $vertex_values, $count, $edges, $domino_options, $total_dominoes, &$max_count) {
        if ($edge_idx == count($edges)) {
            if ($count > $max_count) {
                $max_count = $count;
            }
            return;
        }

        // Prune if remaining edges can't improve the max
        $remaining = count($edges) - $edge_idx;
        if ($count + $remaining <= $max_count) {
            return;
        }

        // Option 1: skip this edge
        backtrack($edge_idx + 1, $used, $vertex_values, $count, $edges, $domino_options, $total_dominoes, $max_count);

        // Option 2: try placing a domino on this edge
        $u = $edges[$edge_idx][0];
        $v = $edges[$edge_idx][1];

        for ($d = 0; $d < $total_dominoes; $d++) {
            if ($used[$d]) continue;

            foreach ($domino_options[$d] as $option) {
                $a = $option[0];
                $b = $option[1];

                // Check if u and v can be assigned a and b respectively
                $valid = true;
                if (isset($vertex_values[$u]) && $vertex_values[$u] != $a) {
                    $valid = false;
                }
                if (isset($vertex_values[$v]) && $vertex_values[$v] != $b) {
